 var keyOf=byDept?function(t){return t.source;}:function(t){return t.vendor_id;},tabs=buildTabs(byDept,rows,keyOf,st),cur=st.tab||'',shown=rows.filter(function(t){return!cur||(keyOf(t)||'')===cur;});
